class a{bucketName="debelingoconangel.appspot.com";storageBaseUrl=`https://storage.googleapis.com/${this.bucketName}/events-archive`;async createArchiveFile(r){try{const e=await fetch("/api/create-archive",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(r)});if(!e.ok){const t=await e.text();throw new Error(`Error al crear archivo (${e.status}): ${t}`)}const s=await e.json();return console.log(`✅ Archivo creado: ${s.fileName} con ${r.events.length} eventos`),{success:!0,fileName:s.fileName}}catch(e){return console.error("Error al crear archivo de archivo:",e),{success:!1,fileName:"",error:e instanceof Error?e.message:"Error desconocido"}}}async archiveExists(r){try{return(await fetch(`${this.storageBaseUrl}/${r}.json`,{method:"HEAD"})).ok}catch{return!1}}async getArchiveData(r){try{const e=await fetch(`${this.storageBaseUrl}/${r}.json`);return e.ok?await e.json():null}catch(e){return console.error(`Error al cargar archivo del año ${r}:`,e),null}}async getAvailableYears(){try{const r=await fetch(`${this.storageBaseUrl}/index.json`);if(r.ok)return(await r.json()).years||[];const e=new Date().getFullYear(),s=[];for(let t=2020;t<e;t++)await this.archiveExists(t)&&s.push(t);return s.sort((t,o)=>o-t)}catch(r){return console.error("Error al obtener años disponibles:",r),[]}}}const c=new a;export{c as default,c as staticFileService};
